const hdr = $input.first().json.headers || {};
if (hdr['x-export-token'] !== '<<EXPORT_TOKEN>>') {
  throw new Error('unauthorized');
}
return [{ json: {
  Tenant_ID: 'bddeba87-9d41-4063-a0e3-be9e6afcd2ba',
  client_ID: 'db88be9e-de13-4205-b0c1-472007c60c36',
  Secret_ID: '<<BC_CLIENT_SECRET>>',
  Company_ID: '9ebc308f-a2c8-ed11-9a88-000d3a8e59a1'
} }];

// Merge all paged responses into invoice headers + item-level lines
const invoices = [];
for (const item of $input.all()) {
  for (const inv of (item.json.value || [])) invoices.push(inv);
}
const headers = [];
const lines = [];
for (const inv of invoices) {
  const kids = inv.salesInvoiceLines || [];
  headers.push({
    invoiceNumber: inv.number,
    customerNumber: inv.customerNumber,
    customerName: inv.customerName,
    invoiceDate: inv.invoiceDate,
    dueDate: inv.dueDate,
    status: inv.status,
    currencyCode: inv.currencyCode,
    totalAmountExcludingTax: inv.totalAmountExcludingTax,
    totalTaxAmount: inv.totalTaxAmount,
    totalAmountIncludingTax: inv.totalAmountIncludingTax,
    discountAmount: inv.discountAmount,
    remainingAmount: inv.remainingAmount,
    orderNumber: inv.orderNumber,
    externalDocumentNumber: inv.externalDocumentNumber,
    salesperson: inv.salesperson,
    shipmentDate: inv.shipmentDate,
    lineCount: kids.length,
    invoiceId: inv.id
  });
  for (const l of kids) {
    lines.push({
      invoiceNumber: inv.number,
      invoiceDate: inv.invoiceDate,
      customerNumber: inv.customerNumber,
      customerName: inv.customerName,
      sequence: l.sequence,
      lineType: l.lineType,
      itemNumber: l.lineObjectNumber,
      description: l.description,
      quantity: l.quantity,
      unitOfMeasureCode: l.unitOfMeasureCode,
      unitPrice: l.unitPrice,
      discountPercent: l.discountPercent,
      discountAmount: l.discountAmount,
      amountExcludingTax: l.amountExcludingTax,
      taxPercent: l.taxPercent,
      totalTaxAmount: l.totalTaxAmount,
      amountIncludingTax: l.amountIncludingTax,
      netAmount: l.netAmount,
      shipmentDate: l.shipmentDate
    });
  }
}
return [{ json: { customer: $('Webhook').first().json.query.customer,
                  invoiceCount: headers.length, lineCount: lines.length,
                  invoices: headers, lines } }];
